SourceCode.Declaration:
/// <summary>
/// Stock count control center: Transfer to counting journal (see HSMobileOpsCountControl::transfer).
/// </summary>
class HSMobileOpsCountTransfer
{
}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsCountMaster master = _args ? _args.record() : null;
    HSMobileOpsCountStage  stage;

    if (!master || !master.RecId)
    {
        throw error('Select a stock count first.');
    }
    select count(RecId) from stage
        where stage.MasterRecId == master.RecId
           && stage.Status      == HSMobileOpsCountStageStatus::Counting;
    if (stage.RecId
     && Box::yesNo(strFmt('%1 counter(s) have not ended their count yet. Transfer what has been counted so far?', stage.RecId),
            DialogButton::No, 'Transfer to counting journal') != DialogButton::Yes)
    {
        return;
    }
    HSMobileOpsCountControl::transfer(master.RecId);
    if (_args && _args.caller() is FormRun)
    {
        FormRun callerForm = _args.caller() as FormRun;
        int     i;
        for (i = 1; i <= callerForm.dataSourceCount(); i++)
        {
            callerForm.dataSource(i).research(true);
        }
    }
}
